// Slack signs every request: the X-Slack-Signature header is v0= followed by the hex
// HMAC-SHA256 of v0:<timestamp>:<raw body>, keyed with the app's signing secret. The raw
// body has to be the bytes Slack sent, so the webhook keeps them, and re-encoding the
// parsed form would not reproduce them. The next node computes the HMAC with the secret
// from n8n's credential store, so the secret never appears in this workflow.
//
// Nothing in the payload is trusted until the signature has been checked. `kind` only
// decides which branch runs after the check.
//
// The payload is decoded from those same signed bytes, never from n8n's parsed body, so
// what the workflow acts on is exactly what Slack signed. Slack sends interactivity as one
// urlencoded field, payload=..., and anything else gets no payload and is refused.
const item = $input.first();
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const headers = item.json.headers || {};
const timestamp = String(headers['x-slack-request-timestamp'] || '');
const urlencoded = /^application\/x-www-form-urlencoded\b/i.test(String(headers['content-type'] || ''));
const field = raw.match(/^payload=([^&]*)$/);
let payload = null;
try {
  payload = urlencoded && field ? JSON.parse(decodeURIComponent(field[1].replace(/\+/g, ' '))) : null;
} catch (error) {
  payload = null;
}
let kind = 'other';
if (payload && payload.type === 'block_actions') {
  const action = (payload.actions || [])[0] || {};
  if (action.action_id === 'ose_decide_approve' || action.action_id === 'ose_decide_reject') kind = 'click';
} else if (payload && payload.type === 'view_submission') {
  const callback = (payload.view || {}).callback_id;
  if (callback === 'ose_decision_edit') kind = 'edit';
  if (callback === 'ose_decision_confirm') kind = 'confirm';
}
return [{ json: {
  base: `v0:${timestamp}:${raw}`,
  signature: String(headers['x-slack-signature'] || ''),
  timestamp,
  payload,
  kind,
} }];

// The dialog a reviewer edits before deciding. Everything it shows comes from the row,
// never from the button, which carries the slug alone. A click by someone not in
// SLACK_DECIDERS, or on an application that is no longer waiting for a decision, gets a
// reply only the clicker sees, through the response_url Slack sent with the click.
//
// The email field starts from the same copy apply 1a and 1b send, from
// automation/emails, which check 10 holds word for word. What the reviewer changes applies
// to this application only. The subject is not editable and comes from the template.
// A rejection always starts from decision-rejected: the no-response variant is apply
// 1a and 1b's own choice for a form that never came back, which is not this case.
const TEMPLATES = {
  approved: `Subject: {{ collective_name }} is approved on Open Collective

Hi,

Welcome on board! We have approved your application to {{ org_name }}.

You can find our hosting documentation here:
https://docs.opencollective.com/open-source-europe

We would also be happy to schedule a short onboarding call to get to know each other a
little better and go through some practical details together. If that would be useful,
please feel free to select a time here:
https://calendly.com/ivan-oce/onboarding-call

Best regards,
The OSE Team`,
  rejected: `Subject: {{ collective_name }} — outcome of your application to {{ org_name }}

Hi,

Thank you for your application to be fiscally hosted by {{ org_name }}, and for taking the
time to share your project with us.

After careful review, we have decided not to move forward with your application. Based on
the information provided, we do not think OSE is the right fiscal host for the
project at this stage.

We appreciate your interest and wish you all the best with the development of your
initiative.

Best regards,
The OSE Team`,
};
const ORG_NAMES = { OSE: 'Open Source Europe' };
// SLACK_DECIDERS lists the Slack user ids allowed to decide, comma separated. Unset or
// empty means nobody: like DRY_RUN, a missing line in .env fails safe.
const DECIDERS = String($env.SLACK_DECIDERS || '').split(',').map((id) => id.trim()).filter(Boolean);
const payload = $('Route by interaction').first().json.payload;
const action = payload.actions[0];
const decision = action.action_id === 'ose_decide_approve' ? 'approved' : 'rejected';
const user = (payload.user || {}).id || '';
const row = $input.first().json || {};
const responseUrl = String(payload.response_url || '');

const refuse = (text) => [{ json: {
  action: 'refuse',
  // Only Slack's own address is ever posted to, whatever the payload says.
  response_url: /^https:\/\/hooks\.slack\.com\//.test(responseUrl) ? responseUrl : '',
  message: { response_type: 'ephemeral', replace_original: false, text },
} }];

if (!DECIDERS.includes(user)) {
  return refuse(':no_entry: Only the people listed in SLACK_DECIDERS can decide from Slack. You can still decide on Open Collective.');
}
if (!row.slug || row.slug !== action.value) {
  return refuse(':warning: This application is not in the pipeline\'s table, so it cannot be decided from Slack. Decide on Open Collective.');
}
if (row.decision || row.stage !== 'awaiting_decision') {
  return refuse(`:information_source: This application is not waiting for a decision any more. Its stage is ${row.stage || 'unknown'}.`);
}

const raw = TEMPLATES[decision];
const vars = { collective_name: row.collective_name, org_name: ORG_NAMES[row.org] || row.org };
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => String(vars[key] || ''));
const cut = raw.indexOf('\n');
const subject = render(raw.slice('Subject: '.length, cut));
const body = render(raw.slice(cut).trimStart());
// An application decided before its form invitation gets no closing email from apply 1a
// or 1b, so the dialog says so instead of offering an email nobody would receive.
const invited = !!row.form_invited_at;
const verb = decision === 'approved' ? 'approve' : 'reject';

const blocks = [
  { type: 'section', text: { type: 'plain_text', text: `You are about to ${verb} ${row.collective_name || row.slug} on Open Collective.` } },
];
if (invited) {
  blocks.push({
    type: 'input', block_id: 'ose_email',
    label: { type: 'plain_text', text: 'Email to the applicant' },
    hint: { type: 'plain_text', text: `Sent by n8n once Open Collective has the decision, with the subject "${subject}". Your edits apply to this application only.`.slice(0, 2000) },
    element: { type: 'plain_text_input', action_id: 'value', multiline: true, initial_value: body, max_length: 2000 },
  });
} else {
  blocks.push({ type: 'section', text: { type: 'plain_text', text: 'This applicant was never invited to the form, so no closing email will be sent. Open Collective sends its own notice.' } });
}
blocks.push({
  type: 'input', block_id: 'ose_note', optional: true,
  label: { type: 'plain_text', text: 'Private note on Open Collective' },
  hint: { type: 'plain_text', text: 'Posted on the application for host admins only. The applicant never sees it.' },
  element: { type: 'plain_text_input', action_id: 'value', multiline: true, max_length: 500 },
});

const view = {
  type: 'modal',
  callback_id: 'ose_decision_edit',
  title: { type: 'plain_text', text: decision === 'approved' ? 'Approve application' : 'Reject application' },
  submit: { type: 'plain_text', text: 'Review' },
  close: { type: 'plain_text', text: 'Cancel' },
  private_metadata: JSON.stringify({ slug: row.slug, decision }),
  blocks,
};
return [{ json: { action: 'open', body: { trigger_id: payload.trigger_id, view } } }];

// views.open answers 200 with ok: false when it refuses, most often because the click's
// trigger_id expired after three seconds. Throwing hands it to the failure alert, since the
// reviewer saw nothing happen and can simply click again.
const answer = $input.first().json || {};
if (answer.ok !== true) throw new Error(`apply 6: Slack refused to open the decision dialog: ${answer.error || 'no answer'}`);
return [];

// The dialog was submitted. Slack waits three seconds for the answer, and the answer is
// the confirmation view, pushed on top of the dialog so its Back button returns to the
// text as it was typed. Nothing has been sent or saved yet.
//
// The confirmation carries the texts to the next step in private_metadata, which Slack
// caps at 3000 characters. That is why the email is capped at 2000 and the note at 500,
// and a pair that still does not fit is sent back as an error on the dialog.
// SLACK_DECIDERS lists the Slack user ids allowed to decide, comma separated. Unset or
// empty means nobody: like DRY_RUN, a missing line in .env fails safe.
const DECIDERS = String($env.SLACK_DECIDERS || '').split(',').map((id) => id.trim()).filter(Boolean);
const payload = $input.first().json.payload;
const view = payload.view || {};
const user = (payload.user || {}).id || '';
const values = (view.state || {}).values || {};
const read = (block) => ((values[block] || {}).value || {}).value;
const errors = (block, text) => [{ json: { response: { response_action: 'errors', errors: { [block]: text } } } }];

if (!DECIDERS.includes(user)) return errors('ose_note', 'Only the people listed in SLACK_DECIDERS can decide from Slack.');
let meta = {};
try { meta = JSON.parse(view.private_metadata || '{}'); } catch (error) { meta = {}; }
if (!meta.slug || !['approved', 'rejected'].includes(meta.decision)) {
  return errors('ose_note', 'This dialog lost track of its application. Close it and click the button again.');
}
const invited = Object.prototype.hasOwnProperty.call(values, 'ose_email');
const email = invited ? String(read('ose_email') || '').trim() : '';
const note = String(read('ose_note') || '').trim();
if (invited && !email) return errors('ose_email', 'The email cannot be empty.');

const next = JSON.stringify({ slug: meta.slug, decision: meta.decision, invited, email, note });
if (next.length > 3000) {
  return errors('ose_email', `Too long to carry to the confirmation by ${next.length - 3000} characters. Shorten the email or the note.`);
}
const approve = meta.decision === 'approved';
const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: approve
    ? '*Confirm to approve this application on Open Collective.*'
    : '*Confirm to reject this application on Open Collective.*' } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: 'Open Collective also sends the applicant its own standard notice. Nothing is added to it. The applicant\'s form answers are saved on the application, where OSE\'s admins and the collective\'s admins can read them.' }] },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: '*Email to the applicant*, from n8n once Open Collective has the decision:' } },
  { type: 'section', text: { type: 'plain_text', text: invited ? email : 'None. This applicant was never invited to the form.' } },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: '*Private note on Open Collective*, for host admins only:' } },
  { type: 'section', text: { type: 'plain_text', text: note || 'None.' } },
];
return [{ json: { response: { response_action: 'push', view: {
  type: 'modal',
  callback_id: 'ose_decision_confirm',
  title: { type: 'plain_text', text: approve ? 'Confirm approval' : 'Confirm rejection' },
  submit: { type: 'plain_text', text: approve ? 'Approve' : 'Reject' },
  close: { type: 'plain_text', text: 'Back' },
  private_metadata: next,
  blocks,
} } } }];

// Confirm was pressed. Slack has already been told to close the dialogs, so what happens
// from here is reported in the application's thread. The person is checked against
// SLACK_DECIDERS again, because the list may have changed since the dialog opened. A person
// no longer on it is told so in the thread, by the refused reply, since their dialog has
// closed.
// SLACK_DECIDERS lists the Slack user ids allowed to decide, comma separated. Unset or
// empty means nobody: like DRY_RUN, a missing line in .env fails safe.
const DECIDERS = String($env.SLACK_DECIDERS || '').split(',').map((id) => id.trim()).filter(Boolean);
const payload = $('Route by interaction').first().json.payload;
const user = payload.user || {};
const allowed = DECIDERS.includes(user.id || '');
let meta = {};
try { meta = JSON.parse((payload.view || {}).private_metadata || '{}'); } catch (error) { return []; }
if (!meta.slug || !['approved', 'rejected'].includes(meta.decision)) return [];
const name = String(user.name || user.username || user.id);
// The note goes to Open Collective as HTML, so the person's text is escaped and only the
// line breaks become markup. It opens with who decided, since Open Collective shows the
// owner of the token as the author whoever pressed Confirm.
const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');
const verb = meta.decision === 'approved' ? 'Approved' : 'Rejected';
const note = String(meta.note || '').trim();
return [{ json: {
  allowed,
  slug: meta.slug,
  decision: meta.decision,
  action: meta.decision === 'approved' ? 'APPROVE' : 'REJECT',
  email: meta.invited ? String(meta.email || '').trim() : '',
  note,
  note_html: `<p>${verb} via Slack by ${escapeHtml(name)}.</p><p>${escapeHtml(note).replace(/\r?\n/g, '<br>')}</p>`,
  decided_by: `<@${user.id}> (${name})`,
  user_id: user.id,
} }];

// processHostApplication and createComment name the application by its id, which the row
// does not hold. Asking for it among the host's pending applications is also the last
// check that Open Collective still waits for a decision.
const row = $('Read the row to decide').first().json;
return [{ json: { request: {
  query: 'query($h: String, $s: String) { host(slug: $h) { hostApplications(limit: 20, status: PENDING, searchTerm: $s) { nodes { id account { slug } } } } }',
  variables: { h: row.host_slug, s: row.slug },
} } }];

// The search matches names and descriptions too, so only the application whose account
// slug is the row's own counts. An error answer, or no such application, stops here and
// the claim is released, so the person can decide on Open Collective or try again.
const answer = $input.first().json || {};
const slug = $('Read the confirmation').first().json.slug;
if (answer.error || Array.isArray(answer.errors)) {
  const detail = answer.error ? (answer.error.message || 'the request failed') : answer.errors.map((e) => e && e.message).join('; ');
  return [{ json: { ok: false, reason: `Open Collective refused the lookup: ${detail}` } }];
}
const nodes = ((((answer.data || {}).host || {}).hostApplications || {}).nodes) || [];
const match = nodes.find((n) => n && n.account && n.account.slug === slug);
if (!match) return [{ json: { ok: false, reason: 'Open Collective has no pending application from this collective any more, so it was probably decided there already' } }];
const confirmation = $('Read the confirmation').first().json;
// The applicant's own answers are saved on the application with the decision, under one
// key so they never overwrite the keys Open Collective or the applicant set. Open
// Collective shows customData to the host's admins and to the collective's own admins,
// never publicly, and the form tells the applicant so. Only what the applicant wrote goes
// in, listed by name: never the AI review, the summary or a reviewer's words, because the
// collective's admins can read it. Reviewer notes go in the private note instead.
const row = $('Read the row to decide').first().json;
let answers = {};
try { answers = JSON.parse(row.answers || '{}'); } catch (error) { answers = { unreadable: String(row.answers || '') }; }
const form = {
  answers,
  contact_email: row.contact_email || '',
  alternative_admin_name: row.alternative_admin_name || '',
  alternative_admin_email: row.alternative_admin_email || '',
  admin_countries: row.admin_countries || '',
  form_submitted_at: row.form_submitted_at || '',
};
return [{ json: { ok: true, application_id: match.id, request: {
  query: 'mutation($a: HostApplicationReferenceInput!, $x: ProcessHostApplicationAction!, $d: JSON) { processHostApplication(hostApplication: $a, action: $x, customData: $d) { hostApplication { id status } } }',
  // No message: Open Collective sends its standard notice, and OSE's own email comes from
  // apply 1a or 1b once the decision is recorded.
  variables: { a: { id: match.id }, x: confirmation.action, d: { oseApplicationForm: form } },
} } }];

// Both outputs of the mutation land here. Only an answer naming the application with the
// status asked for counts as decided.
const answer = $input.first().json || {};
const wanted = $('Read the confirmation').first().json.action === 'APPROVE' ? 'APPROVED' : 'REJECTED';
const result = ((answer.data || {}).processHostApplication || {}).hostApplication || {};
if (!answer.error && !Array.isArray(answer.errors) && result.status === wanted) {
  return [{ json: { ok: true, request: {
    query: 'mutation($c: CommentCreateInput!) { createComment(comment: $c) { id } }',
    variables: { c: {
      hostApplication: { id: $('Choose the pending application').first().json.application_id },
      type: 'PRIVATE_NOTE',
      html: $('Read the confirmation').first().json.note_html,
    } },
  } } }];
}
const detail = answer.error ? (answer.error.message || 'the request failed')
  : Array.isArray(answer.errors) ? answer.errors.map((e) => e && e.message).join('; ')
  : `the application came back as ${result.status || 'unknown'}`;
return [{ json: { ok: false, reason: `Open Collective did not take the decision: ${detail}` } }];

// The decision is on Open Collective. apply 1a or 1b records it and sends the closing
// email, and says so in this thread, so this reply only names who decided here.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const confirmation = $('Read the confirmation').first().json;
const row = $('Read the row to decide').first().json;
if (!row.slack_thread_ts || !row.slack_channel_id) return [];
const answer = $input.first().json || {};
const noted = !answer.error && !Array.isArray(answer.errors) && !!((answer.data || {}).createComment || {}).id;
const done = confirmation.decision === 'approved'
  ? `:white_check_mark: <@${confirmation.user_id}> approved this application on Open Collective from Slack.`
  : `:x: <@${confirmation.user_id}> rejected this application on Open Collective from Slack.`;
const email = confirmation.email
  ? ' The closing email from the dialog goes to the applicant once the decision is recorded.'
  : '';
const note = noted
  ? ' A private note for host admins is on the application.'
  : ` :warning: The private note could not be posted on Open Collective${answer.error ? `: ${escapeSlack(answer.error.message || '')}` : ''}.`;
return [{ json: { channel: row.slack_channel_id, thread_ts: row.slack_thread_ts, text: done + email + note } }];

// Nothing was decided. The reason comes from Open Collective or from the lookup, so it is
// escaped before it reaches the channel.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const confirmation = $('Read the confirmation').first().json;
const row = $('Read the row to decide').first().json;
if (!row.slack_thread_ts || !row.slack_channel_id) return [];
// The mutation runs only after the lookup succeeded, so when it ran, its answer is the
// reason, and otherwise the lookup's is.
const asked = $('Read the decision answer').isExecuted;
const why = asked
  ? $('Read the decision answer').first().json.reason
  : $('Choose the pending application').first().json.reason;
const reason = escapeSlack(String(why || 'No reason was given').slice(0, 400)).replace(/\.?$/, '.');
// A failed lookup means nothing was asked of Open Collective. A failed decision call may
// still have landed, a timeout for one, so the reply says to look before trying again.
const text = asked
  ? `:warning: <@${confirmation.user_id}> pressed Confirm, and Open Collective did not confirm the decision. ${reason} Check the application on Open Collective before trying again. If it shows the decision, the pipeline records it and sends the email as usual.`
  : `:warning: <@${confirmation.user_id}> pressed Confirm, and Open Collective was not asked to decide. ${reason} The decision can be made again, here or on Open Collective.`;
return [{ json: { channel: row.slack_channel_id, thread_ts: row.slack_thread_ts, text } }];

// Someone else is deciding, or has decided, or the row is not waiting for a decision. The
// person who pressed Confirm learns it here, since their dialog has already closed.
const confirmation = $('Read the confirmation').first().json;
const row = $('Read the row to decide').first().json;
if (!row.slack_thread_ts || !row.slack_channel_id) return [];
const reason = !confirmation.allowed
  ? 'Only the people listed in SLACK_DECIDERS can decide from Slack, and they are not on it any more.'
  : row.decision || row.stage !== 'awaiting_decision'
  ? `The application is not waiting for a decision any more. Its stage is ${row.stage || 'unknown'}.`
  : 'Someone else is confirming a decision on it right now.';
return [{ json: { channel: row.slack_channel_id, thread_ts: row.slack_thread_ts,
  text: `:information_source: <@${confirmation.user_id}> pressed Confirm, and nothing was sent. ${reason}` } }];
